# Q3 round 3: update /output/report.json with the Q12-informed single-zone RADEX results (s60) and the carried s53/s55 checks.
# usage: python3 -I s61_update_report_q3r2.py   (re-runnable: removes its own earlier entries, tagged 'Q3r3')
import json,shutil
R='/output/report.json'; shutil.copy(R,'/workspace/out/report_before_q3r3.json'); r=json.load(open(R))
res=r['results']
res=[x for x in res if 'Q3r3' not in x.get('evidence','')]
# drop the round-1 single-zone entries superseded by the Q12-informed refit (numbers retained in out/q3, out/q3b files)
res=[x for x in res if not (x['quantity'].startswith('Single-zone non-LTE (RADEX LVG) constraints on n(H2), Tkin') or x['quantity'].startswith('Robustness of the N, S ladder constraints to the flux-scale'))]
for x in res:
    for k in ('uncertainty','value'):
        if isinstance(x.get(k),str) and 'provisional until refit with the Q12 priors' in x[k]:
            x[k]=x[k].replace('Treat Q3 n,Tk intervals at the disk as provisional until refit with the Q12 priors.','The refit with the Q12 recovery budget is in the Q3r3 entries (s60); the disk numbers here are superseded.')
A=lambda n,v:{'name':n,'value':v}
common=[A('distance','40 Mpc (1" = 194 pc)'),A('RADEX','LAMDA hcn.dat, hco+.dat (H2 collisions), LVG, Tbg 2.73 K, N per 150 km/s; grid Tk 10-300 K, n(H2) 1e3-1e8, interpolated to 0.05 dex in Tk, 0.125 dex in n, 0.1 dex in N and in A=N(HCN)/N(HCO+)'),
 A('data','Xb55 J=2, Xb4f J=3, Xb47 J=4 smoothed to a 10" circular beam, |v-vsys|<350 km/s, pbcor, K km/s (RJ, rest frame); stat S/N 60-440 at the centre, 3-230 at E1,E2,W'),
 A('priors','flat in log n 3-8, log Tk 1-2.48, log N(HCO+) 11.5-19, log A -1..1.5; common filling eta<=1 (flat in ln eta, analytic marginalisation)'),
 A('calibration','10% per band (independent bands) + 7% per line; recovery enters as multipliers on 2-1 and 4-3 relative to 3-2: centre f2 U[0.85,0.95], f4 U[1.03,1.12] (Q12 R55/R4f 1.05-1.18, R47/R4f 0.89-0.97); a common loss of all bands is degenerate with eta'),
 A('likelihood','Gaussian in ln flux, 6 data (3 J x 2 molecules), 5 free parameters (n,Tk,N,A,eta): 1 dof, so a fit is a consistency screen, not a test')]
def E(q,t,v,u,unit,conf,ev,extra=()): return dict(quantity=q,target=t,value=v,uncertainty=u,unit=unit,assumptions=common+list(extra),confidence=conf,evidence='Q3r3: '+ev)
new=[]
new.append(E('Single-zone RADEX constraints on n(H2), Tkin, N(HCO+)/dv, A=N(HCN)/N(HCO+) and thermal pressure from the 10" HCN+HCO+ 2-1,3-2,4-3 ladder at the centre, with the Q12 recovery budget (medians, 68% and 95% intervals of marginal posteriors)',
 'N, S, Bridge positions and their joint fit (shared n,Tk,N,A; own eta)',
 'Centre joint (N+S+Bridge): log n(H2) 4.62 [68%: 3.62,4.88; 95%: 3.12,5.00]; Tk 152 K [86,239; 95%: 55,300 = prior edge]; log A 0.40 [0.30,0.50] (A~2.5, 2-3x HCN-rich, P(A>1)=1.00, P(A>3)=0.21); log N(HCO+)/dv 13.02 [11.82,13.82] cm-2/(km/s); log P/k 6.64 [5.91,7.13] cm-3 K; P(n>1e5)=0.02, P(Tk>50 K)=0.98, P(Tk<30 K)=0.00, P(tau_HCN 3-2>1)=0.68 (median tau 4.4, range 0.1-23). Single positions: N log n 4.50 [3.62,5.00], Tk 152 [61,239], P(n>1e5)=0.10, P(Tk>50)=0.87; S log n 4.50 [3.50,4.88], Tk 152 [77,239], P(n>1e5)=0.07, P(Tk>50)=0.91; Bridge log n 4.50 [3.50,5.00], Tk 136 [61,239], P(n>1e5)=0.10. Result: moderate density n~1e4-1e5 cm-3 (n>1e6 excluded at <~3%), warm gas Tk>~50 K with the upper end set by the prior edge (Tk is a lower limit, not a measurement), HCN column 2-3x HCO+, HCN moderately thick. Best-fit chi2 <1 for 1 dof (consistency only).',
 'n: +-0.6 dex (68%); Tk: lower limit ~50-60 K (68% lower edge 86 K joint, 61-77 K single), upper end unconstrained (prior edge 300 K); A: +-0.1 dex. Without the Q12 recovery term (cal 10%): log n 4.50 [3.62,4.75], Tk 152 [97,170], P(n>1e5)=0.00; with cal 15/10/15%: log n 4.50 [3.62,4.88], Tk 152 [86,239]; wide recovery (f2 0.6-1, f4 1-1.5): log n 4.38 [3.38,5.00], Tk 136 [55,239], logN(HCO+)/dv 13.6 [12.6,14.7]; ratios-only (band scales free): log n 4.62 [3.50,5.88], Tk 69 [39,170], A 10^0.3 [10^-0.2,10^0.4], P(n>1e5) rises to ~0.3 and the thick, cold branch is not excluded. Dropping Xb55 or Xb47: log n 4.4-4.5 [3.5,4.9], Tk 136-152 [69-77,213-239]: no single band drives it.',
 'dex; K; ratio','medium','s60_q3_q12prior.py -> out/q3c/s60_q12prior.txt/json (grid s52_radex_grid.py, library s55_lib.py, s53_ladder_fit.py)',
 [A('tau_interpretation','tau(HCN 3-2) median 4.4 with 68% range 0.1-23: opacity is NOT separated from abundance; combined with p0007 (HCN/H13CN>8), A=1-5.6 on the thin branch is consistent with A~2.5 here')]))
new.append(E('Where the density/temperature information comes from: ladder normalisation vs line ratios, and scenario dependence of the centre constraint',
 'N position (S, Bridge identical within 0.1 dex)',
 'T21/T32 = 2.6 (HCN), 2.0 (HCO+) and T43/T32 = 0.34 (HCN), 0.45 (HCO+) at N (K km/s units; S: 2.7/2.1, 0.32/0.43; Bridge 2.6/2.0, 0.33/0.45). The quoted n and Tk follow from the cross-band normalisation (sub-thermal T21/T32>~2 requires low density and Tk>~50 K): using the three same-J HCN/HCO+ ratios alone (ratios-only) the allowed region widens to n 1e3.5-1e5.9, Tk 39-170 K and P(n>1e5)~0.3. The recovery budget moves the medians by <0.15 dex in n and <~15% in Tk (centre), i.e. it is smaller than the 10%/band calibration scatter. Common loss of all ACA bands changes nothing (absorbed by eta). A large Xb4f-only loss would change the answer strongly (30% loss in Xb4f only: log n 4.38 [3.25,7.38], Tk 49 [11,136]; 50%: n>=1e7, Tk 11 K [10,39]) but Q12 shows the loss relative to Xb55/Xb47 is only 5-18% / 3-12% at the centre.',
 'scenario spread ~0.5 dex in n, factor ~2 in Tk','T_k and n are conditional on the 10-15% band calibration and the Q12 recovery bounds','medium',
 's60_q3_q12prior.py, s55e_xb4f_loss.py -> out/q3c/s60_q12prior.txt, out/q3b/s55e_xb4f_loss.txt',[]))
new.append(E('Disk positions E1, E2, W: ladder fits with PB-model and recovery budgets from Q12, and the centre-vs-disk contrast in Tkin and n',
 'E1 (compact, Q12 recovery ~1), E2 and W (recovery unconstrained, wide prior f2 0.6-1, f4 1-1.5); W HCN 4-3 (2.7 sigma) dropped',
 'E1: log n 4.75 [3.75,5.38], Tk 35 K [20,55; 95%: 11,86], log A 0.50 [0.40,0.50], log N(HCO+)/dv 12.62 [11.3,13.9], P(Tk<30)=0.38, P(Tk>50)=0.18, P(n>1e5)=0.34. E2: log n 5.00 [3.62,5.50], Tk 44 [20,86], P(n>1e5)=0.44 (unconstrained: log n 95% 3-7). W: log n 4.38 [3.5,5.1], Tk 61 [25,152], not constrained (HCN 4-3 limit, wide recovery). Contrast with the centre joint fit (independent marginals; calibration shared by the positions is not cancelled, so conservative): P(Tk_E1<Tk_centre)=0.98 (Q12-informed), 0.99 (no recovery term), 0.95 (PB error x2), 0.89 (wide recovery), 0.85 (ratios-only); E2 0.94/0.99/0.90/0.84/0.81; W 0.82/0.96/0.80/0.72/0.69. P(n_disk>n_centre) is only 0.45-0.67 for all three: no density contrast. The observed driver is the faster fall of T43/T32 and rise of T21/T32 in HCN (E1 HCN T21/T32 3.75, T43/T32 0.16; HCO+ 2.4, 0.34) vs the centre (2.6, 0.34; 2.0, 0.45). A disk-vs-centre Tk difference at E1 is therefore supported at the ~2 sigma level (P~0.95-0.98) under Q12-informed priors, but drops to P~0.85-0.89 if the recovery of E1 is not as Q12 finds (compact), and is not established at E2 or W.',
 'E1 Tk 35 K (68%: 20-55 K); contrast probabilities 0.85-0.98 depending on the recovery/PB scenario; E2, W unconstrained','PB response inferred from noise maps (ACA PB FWHM 58/37/30"; PB gain at E1 0.96/0.89/0.81 for Xb55/Xb4f/Xb47); the smooth(pbcor) vs smooth(pbcor*PB)/PB test differs by 10-35% at Xb47 E1,W (HCN 0.66,0.51): the per-line PB error is max(0.3(1-PB), 0.5|1-A/B|)','low','s60_q3_q12prior.py; s55a_pb_snr.py -> out/q3c/s60_q12prior.txt, out/q3b/s55a_pb_snr.txt',
 [A('E2,W','Q12: E2 recovery and W HCN recovery unconstrained; W HCO+ alpha~1; the wide recovery prior is used and the results are labelled unconstrained')]))
new.append(E('Is any N vs S vs Bridge difference in n, Tk or A significant at 10"? Power of the 10" ladder and a two-zone injection',
 'N, S, Bridge at 10"',
 'No. The posteriors of N, S and Bridge are the same within 0.1 dex in n and 15% in Tk: P(Tk_N>Tk_S)=0.48-0.54, P(n_N>n_S)=0.51-0.53 (N vs Bridge 0.50-0.54; S vs Bridge 0.47-0.54) in all Q12-informed scenarios. Evidence comparison (s53, band scales common): ln B(separate/shared) = -6.3 (N vs S), -7.3 (N vs Bridge), -7.1 (S vs Bridge), delta chi2(shared-separate) 2.1/0.2/0.2 for 4 extra parameters (p 0.7-0.99): shared (n,Tk,N,A) is preferred. Power: the 10" N/S ratio-of-ratios is 1.119 +- 0.14 (7% per line independent), so a 2 sigma detection needs a difference >32% (15% if calibration cancels); beams overlap (N-S pixel noise correlation 0.71, N-Bridge 0.97, S-Bridge 0.84). Two-zone injection: a common envelope HCN/HCO+(3-2) = 0.425 plus the measured compact cores (Xb4b r<0.5": N R=0.92, S R=0.41; core fractions of the 10" 3-2 flux 0.19/0.10 HCN/HCO+ at N, 0.07/0.08 at S) reproduces the observed 10" N/S = 1.116 (observed 1.119+-0.14): the 10" ratio difference is consistent with dilution of a nuclear contrast by a common envelope. Core-subtracted N envelope: log n 4.38 [3.50,5.00], Tk 86 [31,191], P(n>1e5)=0.13; S envelope log n 4.12 [3.38,4.75], Tk 108 [49,170]; nuclear n,Tk difference at the 0.25" scale is not measurable here (no ladder at that resolution: Xb4b is J=3-2 only).',
 'ratio-of-ratios 1.12+-0.14; 2 sigma detectability 1.32 (1.15 if calibration cancels)','Q1 (p0005) shows R_core(N)~0.97 vs R(S)~0.45 at 0.25"; at 10" this contrast is diluted to 1.12','medium','s53_ladder_fit.py, s55c_ratios_recovery_power.py, s55d_core_A_tests.py, s60_q3_q12prior.py -> out/q3/s53_ladder_fit.txt, out/q3b/s55c_ratios_recovery_power.txt, s55d_core_A_tests.txt',[]))
new.append(E('Abundance ratio A=N(HCN)/N(HCO+), beam-filling difference between HCN and HCO+, line width, and RADEX geometry: robustness of the centre result',
 'N and S at 10"',
 'A: log A 0.40 [0.40,0.50] (N), 0.40 [0.30,0.50] (S) when HCN and HCO+ share the filling; if HCN is more compact (eta_HCN=q eta_HCO+) A rises: q=0.5 log A 0.80, q=0.25 1.00, q=0.1 1.40; for q log-uniform 0.1-1 log A 0.7 [0.5,1.1] (N). The 10" data cannot tell A from q (degenerate). If HCN fills more (q log-uniform 0.1-3) log A 0.6 [0.2,1.0]; A<1 is permitted only then. Consistent with the thin-branch A of p0007 (1-5.6, median 1.8 for the T_b discriminator) and not with A~1 unless q~1.5-3. Line width: w=60-300 km/s changes log n by <=0.13 dex and Tk by <10%; N is per km/s so independent of w. Geometry: plane-parallel slab gives log n 3.75 [3.0,4.75], Tk 80 [28,112] (about 0.5 dex lower n than LVG; coarse grid, s53). H13CN tau bound (tau_HCN 4-3<3.8/6.4/12.8) removes only the tau>~4 tail (log n 4.50 [3.75,5.00], P(n>1e5)=0.10 at N). Compare: n(H2) from N/dv would require an assumed X(HCO+) and path length and is not quoted as a measurement; N(HCO+)/dv ~1e13 cm-2/(km/s) (1e11.8-1e13.8) is the quantity the fit constrains (weakly, because N and eta are degenerate: eta posterior unconstrained below 1).',
 'log A +-0.1 dex at fixed q; q unconstrained -> log A 0.4-1.4','A, q and eta are degenerate at 10" with a 1-dof ladder','low','s55d_core_A_tests.py, s53_ladder_fit.py -> out/q3b/s55d_core_A_tests.txt, out/q3/s53_ladder_fit.txt',[]))
res=[x for x in res]+new
r['results']=res
# recipe stage
rec=r['recipe']; n=max(s['order'] for s in rec)
rec=[s for s in rec if 'Q3r3' not in s.get('description','')]
rec.append({'order':n+1,'stage':'modelling','description':'Q3r3: Q12-informed refit of the single-zone RADEX ladder (relative recovery multipliers on 2-1 and 4-3, centre/E1 informed, E2/W wide; independent 10%/band calibration; PB error from noise-map PB and PB-handling test); contrasts between positions','software':'radex_lvg, numpy, scipy','parameters':[{'name':'recovery centre','value':'f2 U[0.85,0.95], f4 U[1.03,1.12]'},{'name':'recovery E1','value':'0.95-1.05'},{'name':'recovery E2,W','value':'f2 0.6-1, f4 1-1.5'},{'name':'calibration','value':'10% per band + 7% per line'}],'scripts':['/workspace/scripts/s55_lib.py','/workspace/scripts/s55a_pb_snr.py','/workspace/scripts/s60_q3_q12prior.py','/workspace/scripts/s61_update_report_q3r2.py']})
r['recipe']=rec
json.dump(r,open(R,'w'),indent=1)
from collections import Counter
print(len(res),Counter(x['confidence'] for x in res))
